args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?director ?directorLabel ?birthPlace ?birthPlaceLabel WHERE {
  dbr:Guai_ai_vinti dbo:director ?director .
  ?director dbo:birthPlace ?birthPlace .
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER (langMatches(lang(?directorLabel),"en")) }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel . FILTER (langMatches(lang(?birthPlaceLabel),"en")) }
}

